CREATE TYPE "MaterialCategory" AS ENUM ('CRT','LCD_PANEL','PCB','CABLE','BATTERY','MOTOR','MAGNET','PLASTIC','OTHER');
CREATE TYPE "LotCondition" AS ENUM ('INTACT','DAMAGED','PARTIAL');
CREATE TYPE "LocationPrecision" AS ENUM ('GPS','MANUAL');
CREATE TYPE "LotStatus" AS ENUM ('CREATED','QUOTE_REQUESTED','QUOTE_RECEIVED','COLLECTOR_CONFIRMED','RECYCLER_CONFIRMED','HANDED_OVER','PAID','CANCELLED','DISPUTED');
CREATE TABLE "Lot" ("id" TEXT NOT NULL, "collectorId" TEXT NOT NULL, "materialCategory" "MaterialCategory" NOT NULL, "materialSubcategory" TEXT, "condition" "LotCondition" NOT NULL, "weight" DOUBLE PRECISION NOT NULL, "photoPath" TEXT, "photoUrl" TEXT, "estimatedValue" DOUBLE PRECISION, "quotedPrice" DOUBLE PRECISION, "finalPrice" DOUBLE PRECISION, "collectionLatitude" DOUBLE PRECISION, "collectionLongitude" DOUBLE PRECISION, "collectionAreaName" TEXT, "collectionLocationPrecision" "LocationPrecision", "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "expiresAt" TIMESTAMP(3), "status" "LotStatus" NOT NULL DEFAULT 'CREATED', "notes" VARCHAR(1000), "version" INTEGER NOT NULL DEFAULT 1, CONSTRAINT "Lot_pkey" PRIMARY KEY ("id"));
CREATE INDEX "Lot_collectorId_idx" ON "Lot"("collectorId"); CREATE INDEX "Lot_status_idx" ON "Lot"("status"); CREATE INDEX "Lot_createdAt_idx" ON "Lot"("createdAt"); CREATE INDEX "Lot_materialCategory_idx" ON "Lot"("materialCategory"); CREATE INDEX "Lot_collectorId_createdAt_idx" ON "Lot"("collectorId","createdAt");
ALTER TABLE "Lot" ADD CONSTRAINT "Lot_collectorId_fkey" FOREIGN KEY ("collectorId") REFERENCES "Collector"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
